const char *r5xx_pm4_opname(uint32_t opcode)
{
    for (size_t i = 0; i < N(pm4_names); i++) {
        if (pm4_names[i].op == opcode) {
            return pm4_names[i].name;
        }
    }
    return NULL;
}
